import type { HTMLAttributes } from 'react';
import { cn } from '../utils/cn';
import { useTheme } from './ThemeProvider';
import type { BrandPreset } from './presets';

export interface LogoProps extends HTMLAttributes<HTMLSpanElement> {
  /** Mark size in px. */
  size?: number;
  /** Show the product name next to the mark. */
  wordmark?: boolean;
  /** Override the preset from ThemeProvider. */
  brand?: BrandPreset;
}

/** The active brand's mark, optionally with its wordmark. */
export function Logo({ size = 28, wordmark = false, brand, className, ...props }: LogoProps) {
  const theme = useTheme();
  const active = brand ?? theme.brand;
  return (
    <span
      role="img"
      aria-label={active.name}
      className={cn('inline-flex items-center gap-[7px]', className)}
      {...props}
    >
      {active.mark(size)}
      {wordmark && (
        <span
          aria-hidden="true"
          className="font-sans font-bold tracking-[-0.02em] text-foreground"
          style={{ fontSize: Math.round(size * 0.64) }}
        >
          {active.name}
          <span className="text-primary">.</span>
        </span>
      )}
    </span>
  );
}

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  useRef,
  useSyncExternalStore,
  type ReactNode,
} from 'react';
import { PALETTES, type PaletteId } from '@gntik-ai/tokens/runtime';
import { gntikPreset, type BrandPreset } from './presets';
import type { MotionMode, ResolvedTheme, ThemeMode } from './theme-script';

export { themeScript, type MotionMode, type ThemeMode, type ResolvedTheme } from './theme-script';

/** Theme class per resolved mode. Light is the token default (:root), so it adds no class. */
const THEME_CLASS: Record<ResolvedTheme, string> = { dark: 'dark', light: '', high_contrast: 'high_contrast' };
const ALL_CLASSES = ['dark', 'high_contrast'];
function isPalette(value: string): value is PaletteId {
  return PALETTES.some((id) => id === value);
}

const SYSTEM_QUERIES = ['(prefers-color-scheme: light)', '(prefers-contrast: more)'];

interface ThemeContextValue {
  palette: PaletteId;
  setPalette: (palette: PaletteId) => void;
  motion: MotionMode;
  setMotion: (motion: MotionMode) => void;
  mode: ThemeMode;
  resolved: ResolvedTheme;
  setMode: (mode: ThemeMode) => void;
  brand: BrandPreset;
}

const DEFAULT_THEME: ThemeContextValue = {
  palette: 'green',
  setPalette: () => {},
  motion: 'system',
  setMotion: () => {},
  mode: 'dark',
  resolved: 'dark',
  setMode: () => {},
  brand: gntikPreset,
};

export const ThemeContext = createContext<ThemeContextValue | null>(null);

function systemTheme(): ResolvedTheme {
  if (typeof window === 'undefined' || !window.matchMedia) return 'dark';
  if (window.matchMedia('(prefers-contrast: more)').matches) return 'high_contrast';
  return window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark';
}

function subscribeSystem(onChange: () => void) {
  if (typeof window === 'undefined' || !window.matchMedia) return () => {};
  const queries = SYSTEM_QUERIES.map((q) => window.matchMedia(q));
  queries.forEach((q) => q.addEventListener('change', onChange));
  return () => queries.forEach((q) => q.removeEventListener('change', onChange));
}

function readStored(key: string): ThemeMode | null {
  try {
    const v = localStorage.getItem(key);
    return v === 'dark' || v === 'light' || v === 'high_contrast' || v === 'system' ? v : null;
  } catch {
    return null;
  }
}

/** Same-tab writes (the `storage` event only fires in other tabs). */
const storeListeners = new Set<() => void>();

function subscribeStored(onChange: () => void) {
  storeListeners.add(onChange);
  if (typeof window !== 'undefined') window.addEventListener('storage', onChange);
  return () => {
    storeListeners.delete(onChange);
    if (typeof window !== 'undefined') window.removeEventListener('storage', onChange);
  };
}

const serverStored = () => null;
const serverSystem = (): ResolvedTheme => 'dark';

export interface ThemeProviderProps {
  children: ReactNode;
  /** App motion preference. System preserves the OS reduced-motion setting. */
  defaultMotion?: MotionMode;
  /** Motion storage key; null disables persistence. */
  motionStorageKey?: string | null;
  /** Mode when nothing is stored. Dark is the kit default. */
  defaultMode?: ThemeMode;
  /**
   * Mode for the server render and hydration (e.g. read from a cookie); defaults to `defaultMode`.
   * The stored choice, if any, applies right after hydration.
   */
  initialMode?: ThemeMode;
  /** Apply this theme while retaining the user's stored page preference. */
  forcedMode?: ResolvedTheme;
  /** Named colour palette; defaults to brand.palette, then green. */
  palette?: PaletteId;
  /** Palette storage is opt-in. Null (default) keeps the choice in memory. */
  paletteStorageKey?: string | null;
  /** Brand preset (name, logo and optional palette). */
  brand?: BrandPreset;
  /** localStorage key; pass `null` to disable persistence. */
  storageKey?: string | null;
  /** Element that receives the theme class. Defaults to <html>. */
  target?: () => HTMLElement | null;
}

/**
 * Applies the theme class to <html> (dark · light · high_contrast, or follows the OS),
 * persists the choice and exposes the brand preset. SSR-safe: the server and hydration render
 * use `initialMode ?? defaultMode`; the stored mode and the OS preference are read through
 * useSyncExternalStore, so they apply right after hydration without a mismatch. To avoid a
 * flash on load, inline `themeScript()` in the document <head>.
 */
export function ThemeProvider({
  children,
  defaultMotion = 'system',
  motionStorageKey = 'gntik-motion',
  defaultMode = 'dark',
  initialMode,
  forcedMode,
  brand = gntikPreset,
  palette: paletteProp,
  paletteStorageKey = null,
  storageKey = 'gntik-theme',
  target = () => (typeof document === 'undefined' ? null : document.documentElement),
}: ThemeProviderProps) {
  const defaultPalette = paletteProp ?? brand.palette ?? 'green';
  const [localPalette, setLocalPalette] = useState<PaletteId | null>(null);
  const getStoredPalette = useCallback(() => {
    if (paletteStorageKey == null) return null;
    try {
      return localStorage.getItem(paletteStorageKey);
    } catch {
      return null;
    }
  }, [paletteStorageKey]);
  const storedPalette = useSyncExternalStore(subscribeStored, getStoredPalette, serverStored);
  const paletteChoice = storedPalette ?? localPalette ?? defaultPalette;
  const palette = isPalette(paletteChoice) ? paletteChoice : 'green';
  const warnedPalettes = useRef(new Set<string>());
  useEffect(() => {
    if (
      process.env.NODE_ENV !== 'production' &&
      !isPalette(paletteChoice) &&
      !warnedPalettes.current.has(paletteChoice)
    ) {
      warnedPalettes.current.add(paletteChoice);
      console.warn(`Unknown palette "${paletteChoice}"; using green.`);
    }
  }, [paletteChoice]);
  const setPalette = useCallback(
    (next: PaletteId) => {
      setLocalPalette(next);
      if (paletteStorageKey == null) return;
      try {
        localStorage.setItem(paletteStorageKey, next);
      } catch {}
      storeListeners.forEach((listener) => listener());
    },
    [paletteStorageKey],
  );

  const [localMotion, setLocalMotion] = useState<MotionMode>(defaultMotion);
  const getStoredMotion = useCallback(() => {
    if (motionStorageKey == null) return null;
    try {
      return localStorage.getItem(motionStorageKey) === 'reduce' ? 'reduce' : null;
    } catch {
      return null;
    }
  }, [motionStorageKey]);
  const storedMotion = useSyncExternalStore(subscribeStored, getStoredMotion, serverStored);
  const motion = storedMotion ?? localMotion;

  useEffect(() => {
    const el = target();
    if (motion === 'reduce') el?.setAttribute('data-motion', 'reduce');
    else el?.removeAttribute('data-motion');
  }, [motion, target]);

  const setMotion = useCallback(
    (next: MotionMode) => {
      setLocalMotion(next);
      if (motionStorageKey == null) return;
      try {
        if (next === 'reduce') localStorage.setItem(motionStorageKey, next);
        else localStorage.removeItem(motionStorageKey);
      } catch {}
      storeListeners.forEach((listener) => listener());
    },
    [motionStorageKey],
  );

  const [localMode, setLocalMode] = useState<ThemeMode>(initialMode ?? defaultMode);
  const getStored = useCallback(() => (storageKey ? readStored(storageKey) : null), [storageKey]);
  const stored = useSyncExternalStore(subscribeStored, getStored, serverStored);
  const system = useSyncExternalStore(subscribeSystem, systemTheme, serverSystem);
  const mode = stored ?? localMode;
  const resolved = forcedMode ?? (mode === 'system' ? system : mode);

  useEffect(() => {
    const el = target();
    if (!el) return;
    el.classList.remove(...ALL_CLASSES);
    const cls = THEME_CLASS[resolved];
    if (cls) el.classList.add(cls);
    el.style.colorScheme = resolved === 'light' ? 'light' : 'dark';
    el.dataset.brand = brand.id;
    el.dataset.palette = palette;
  }, [resolved, brand.id, palette, target]);

  const setMode = useCallback(
    (next: ThemeMode) => {
      setLocalMode(next);
      if (!storageKey) return;
      try {
        localStorage.setItem(storageKey, next);
      } catch {}
      storeListeners.forEach((l) => l());
    },
    [storageKey],
  );

  const value = useMemo(
    () => ({ mode, resolved, setMode, brand, motion, setMotion, palette, setPalette }),
    [mode, resolved, setMode, brand, motion, setMotion, palette, setPalette],
  );
  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

/** Current theme and brand. Outside a provider it reports the dark default and the gntik preset. */
export function useTheme(): ThemeContextValue {
  return useContext(ThemeContext) ?? DEFAULT_THEME;
}

import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import { currentPalette, observeTheme } from '@gntik-ai/tokens/runtime';
import { useRender } from '@base-ui/react/use-render';
import { cn } from '../utils/cn';
import { PortalContainerContext } from '../utils/portal';
import { ThemeContext, useTheme, type ResolvedTheme } from './ThemeProvider';

export interface ThemeScopeProps extends Omit<useRender.ComponentProps<'div'>, 'className'> {
  theme: ResolvedTheme;
  className?: string;
}

/** Applies a theme to a subtree and its overlays; mode/setMode still control the page. */
export function ThemeScope({ theme, children, className, render, ref, ...props }: ThemeScopeProps) {
  const page = useTheme();
  const [scopeElement, setScopeElement] = useState<HTMLElement | null>(null);
  const subscribe = useCallback(
    (changed: () => void) => (scopeElement ? observeTheme(changed, scopeElement) : () => {}),
    [scopeElement],
  );
  const getPalette = useCallback(
    () => (scopeElement ? currentPalette(scopeElement) : page.palette),
    [scopeElement, page.palette],
  );
  const palette = useSyncExternalStore(subscribe, getPalette, () => page.palette);
  const value = useMemo(() => ({ ...page, resolved: theme, palette }), [page, theme, palette]);
  const [container, setContainer] = useState<HTMLDivElement>();
  const initialTheme = useRef(theme);

  useEffect(() => {
    const portal = document.createElement('div');
    portal.className = initialTheme.current;
    portal.dataset.themeScopePortal = initialTheme.current;
    document.body.appendChild(portal);
    // Publish the mounted DOM node so already-open overlays also receive the container.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setContainer(portal);
    return () => portal.remove();
  }, []);

  useEffect(() => {
    if (!container) return;
    container.setAttribute('class', theme);
    container.setAttribute('data-theme-scope-portal', theme);
    container.setAttribute('data-palette', palette);
  }, [container, theme, palette]);

  const element = useRender({
    defaultTagName: 'div',
    render,
    ref: [ref ?? null, setScopeElement],
    props: { ...props, className: cn(theme, className), 'data-theme-scope': theme, children },
  });

  return (
    <ThemeContext.Provider value={value}>
      <PortalContainerContext.Provider value={container}>{element}</PortalContainerContext.Provider>
    </ThemeContext.Provider>
  );
}

import type { PaletteId } from '@gntik-ai/tokens/runtime';
import type { ReactNode } from 'react';
import { MUSEMATIC_MARK_PATH } from './musematic-mark';

/**
 * A brand preset supplies name, logo and an optional named kit palette.
 * Green is the default; high contrast is shared by every palette.
 */
export interface BrandPreset {
  id: string;
  /** Named palette from @gntik-ai/tokens; green when omitted. */
  palette?: PaletteId;
  /** Product name, used in the wordmark and as the logo's accessible name. */
  name: string;
  /** Renders the square mark at `size` px. */
  mark: (size: number) => ReactNode;
}

/** Neutral default: a token-coloured monogram, no product named. */
export const gntikPreset: BrandPreset = {
  id: 'gntik',
  name: 'gntik',
  mark: (size) => (
    <svg width={size} height={size} viewBox="0 0 64 64" aria-hidden="true" className="block shrink-0">
      <rect width="64" height="64" rx="14" className="fill-chrome" />
      <path
        d="M41 24.5A11 11 0 1 0 43 32h-11"
        fill="none"
        strokeWidth="6"
        strokeLinecap="round"
        className="stroke-primary"
      />
    </svg>
  ),
};

export const musematicPreset: BrandPreset = {
  id: 'musematic',
  name: 'musematic',
  mark: (size) => (
    <svg width={size} height={size} viewBox="0 0 64 64" aria-hidden="true" className="block shrink-0">
      <rect width="64" height="64" rx="14" fill="#0C2017" />
      <svg x="9" y="9" width="46" height="46" viewBox="0 0 512 512">
        <path fill="#33CE73" fillRule="evenodd" d={MUSEMATIC_MARK_PATH} />
      </svg>
    </svg>
  ),
};

/**
 * Falcone — PLACEHOLDER until the product's logo artwork lands: a token-coloured "F" monogram.
 * Swap `mark` for the real artwork (as musematic does); the name and id stay.
 */
export const falconePreset: BrandPreset = {
  id: 'falcone',
  name: 'Falcone',
  mark: (size) => (
    <svg width={size} height={size} viewBox="0 0 64 64" aria-hidden="true" className="block shrink-0">
      <rect width="64" height="64" rx="14" className="fill-chrome" />
      <path
        d="M24 46V18h18M24 32h13"
        fill="none"
        strokeWidth="6"
        strokeLinecap="round"
        strokeLinejoin="round"
        className="stroke-primary"
      />
    </svg>
  ),
};

export const presets = { gntik: gntikPreset, musematic: musematicPreset, falcone: falconePreset } as const;

import { PALETTES, type PaletteId } from '@gntik-ai/tokens/runtime';

/**
 * Server-safe theme helpers: no React, no 'use client'. Import from `@gntik-ai/ui/theme-script`
 * in a React Server Component (e.g. a Next.js root layout); the main entry re-exports them.
 */

export type ThemeMode = 'dark' | 'light' | 'high_contrast' | 'system';
export type ResolvedTheme = Exclude<ThemeMode, 'system'>;
export type MotionMode = 'system' | 'reduce';

export interface ThemeScriptOptions {
  palette?: PaletteId;
  paletteStorageKey?: string | null;
  motionStorageKey?: string | null;
  defaultMotion?: MotionMode;
}

/**
 * Inline script for <head> that applies the stored theme before first paint.
 * Usage: `<script dangerouslySetInnerHTML={{ __html: themeScript() }} />`.
 */
export function themeScript(
  storageKey = 'gntik-theme',
  defaultMode: ThemeMode = 'dark',
  {
    motionStorageKey = 'gntik-motion',
    defaultMotion = 'system',
    palette = 'green',
    paletteStorageKey = null,
  }: ThemeScriptOptions = {},
) {
  const motionRead = motionStorageKey == null ? 'null' : `localStorage.getItem(${JSON.stringify(motionStorageKey)})`;
  const motionChoice = defaultMotion === 'reduce' ? 'true' : `${motionRead}==='reduce'`;
  const paletteRead =
    paletteStorageKey == null ? '' : `try{p=localStorage.getItem(${JSON.stringify(paletteStorageKey)})||p}catch(_){}`;
  const paletteScript = `(function(){var p=${JSON.stringify(palette)};${paletteRead}document.documentElement.dataset.palette=${JSON.stringify(PALETTES)}.indexOf(p)<0?'green':p})();`;
  return (
    `(function(){try{var m=localStorage.getItem(${JSON.stringify(storageKey)})||${JSON.stringify(defaultMode)};if(m==='system'){var q=function(s){return window.matchMedia(s).matches};m=q('(prefers-contrast: more)')?'high_contrast':q('(prefers-color-scheme: light)')?'light':'dark'}var e=document.documentElement;e.classList.remove('dark','high_contrast');if(m!=='light')e.classList.add(m);e.style.colorScheme=m==='light'?'light':'dark'}catch(_){}})();` +
    `(function(){try{var e=document.documentElement;if(${motionChoice})e.dataset.motion='reduce';else delete e.dataset.motion}catch(_){}})();` +
    paletteScript
  );
}
